// =====================================================================================================
// Power Query (M) for the churn dashboard. Generated by `python -m src.powerbi_docs`.
//
// Create one blank query per section below (Home > Transform data > New source > Blank query), open Advanced Editor,
// paste the code, and rename the query to the name in the section heading. Untick 'Enable load' on Customers_Raw.
//
// The star schema is built from ONE file: output/customer_churn_predictions.csv, produced by `python -m src.predict`.
// Dimensions are static lists on purpose: they fix the order and labels, and include every level even if it has no customers.
// NOTE: this M was written without access to Power BI Desktop and has not been run. See BUILD_GUIDE.md, step 3, for the check.
// =====================================================================================================

// ===== Parameter: DataPath =====
// Home > Transform data > Manage parameters > New parameter. Name: DataPath. Type: Text. Current value: the full path to the CSV,
// for example C:\Users\you\customer-churn-prediction-powerbi\output\customer_churn_predictions.csv
// Power Query has no relative paths, so a parameter is how the file location stays out of the queries. Change it once to repoint everything.
"C:\path\to\customer-churn-prediction-powerbi\output\customer_churn_predictions.csv" meta [IsParameterQuery = true, Type = "Text", IsParameterQueryRequired = true]

// ===== Query: Customers_Raw  (staging only: untick Enable load) =====
let
    Source = Csv.Document(File.Contents(DataPath), [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    PromotedHeaders = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    // The culture argument fixes the decimal separator, so the file loads the same on any regional setting.
    TypedColumns = Table.TransformColumnTypes(
        PromotedHeaders,
        {
            {"CustomerID", type text},
            {"Churn", type text},
            {"ChurnFlag", Int64.Type},
            {"CustomerStatus", type text},
            {"ChurnProbability", type number},
            {"RiskCategory", type text},
            {"RiskOrder", Int64.Type},
            {"ValueSegment", type text},
            {"RetentionSegment", type text},
            {"MonthlyCharges", type number},
            {"TotalCharges", type number},
            {"ExpectedMonthlyRevenueAtRisk", type number},
            {"tenure", Int64.Type},
            {"TenureGroup", type text},
            {"TenureGroupOrder", Int64.Type},
            {"Contract", type text},
            {"InternetService", type text},
            {"PaymentMethod", type text},
            {"PaperlessBilling", type text},
            {"AutoPay", type text},
            {"NumberOfServices", Int64.Type},
            {"ProtectiveAddOnCount", Int64.Type},
            {"ChargeBand", type text},
            {"ChargeBandOrder", Int64.Type},
            {"gender", type text},
            {"SeniorCitizen", type text},
            {"Partner", type text},
            {"Dependents", type text},
            {"PhoneService", type text},
            {"MultipleLines", type text},
            {"OnlineSecurity", type text},
            {"OnlineBackup", type text},
            {"DeviceProtection", type text},
            {"TechSupport", type text},
            {"StreamingTV", type text},
            {"StreamingMovies", type text},
            {"TopRiskDriver1", type text},
            {"TopRiskDriver2", type text},
            {"TopRiskDriver3", type text},
            {"TopProtectiveDriver1", type text},
            {"DataSplit", type text}
        },
        "en-US"
    )
in
    TypedColumns

// ===== Query: FactCustomer =====
// Grain: one row per customer. Adds three columns for the visuals and drops the order columns, which live on the dimensions.
let
    Source = Customers_Raw,
    // TopRiskDriver1 reads 'feature = value'; cutting at ' = ' groups drivers by feature (tenure = 1 and tenure = 2 become one: tenure).
    AddDriverFeature = Table.AddColumn(Source, "TopRiskDriverFeature", each if [TopRiskDriver1] = null then null else Text.BeforeDelimiter([TopRiskDriver1], " = "), type text),
    // Probability in 5-point bins for the histogram. The top bin is capped so a probability of exactly 1.0 stays in 95-100.
    AddBinStart = Table.AddColumn(AddDriverFeature, "ProbabilityBinStart", each Number.Min(Number.RoundDown([ChurnProbability] * 20, 0), 19) / 20, type number),
    AddBinLabel = Table.AddColumn(AddBinStart, "ProbabilityBin", each Text.From(Number.Round([ProbabilityBinStart] * 100, 0)) & "-" & Text.From(Number.Round([ProbabilityBinStart] * 100, 0) + 5) & "%", type text),
    RemoveOrderColumns = Table.RemoveColumns(AddBinLabel, {"RiskOrder", "TenureGroupOrder", "ChargeBandOrder"})
in
    RemoveOrderColumns

// ===== Query: DimContract =====
let
    Source = #table(
        type table [Contract = text, ContractOrder = Int64.Type],
        {
            {"Month-to-month", 1},
            {"One year", 2},
            {"Two year", 3}
        }
    )
in
    Source

// ===== Query: DimInternetService =====
let
    Source = #table(
        type table [InternetService = text, InternetServiceOrder = Int64.Type],
        {
            {"DSL", 1},
            {"Fiber optic", 2},
            {"No", 3}
        }
    )
in
    Source

// ===== Query: DimPaymentMethod =====
let
    Source = #table(
        type table [PaymentMethod = text, PaymentMethodOrder = Int64.Type],
        {
            {"Electronic check", 1},
            {"Mailed check", 2},
            {"Bank transfer (automatic)", 3},
            {"Credit card (automatic)", 4}
        }
    )
in
    Source

// ===== Query: DimTenureGroup =====
let
    Source = #table(
        type table [TenureGroup = text, TenureGroupOrder = Int64.Type],
        {
            {"0-12", 1},
            {"13-24", 2},
            {"25-48", 3},
            {"49+", 4}
        }
    )
in
    Source

// ===== Query: DimChargeBand =====
let
    Source = #table(
        type table [ChargeBand = text, ChargeBandOrder = Int64.Type],
        {
            {"<=35", 1},
            {"35-65", 2},
            {"65-95", 3},
            {">95", 4}
        }
    )
in
    Source

// ===== Query: DimRiskCategory =====
let
    Source = #table(
        type table [RiskCategory = text, RiskOrder = Int64.Type, ColorHex = text, Definition = text],
        {
            {"Low", 1, "#B8C2CF", "Predicted probability below 0.30"},
            {"Medium", 2, "#E8B4B0", "0.30 to 0.70"},
            {"High", 3, "#C0504D", "Above 0.70"}
        }
    )
in
    Source

// ===== Query: DimCustomerStatus =====
let
    Source = #table(
        type table [CustomerStatus = text, StatusOrder = Int64.Type],
        {
            {"Active", 1},
            {"Churned", 2}
        }
    )
in
    Source

// ===== Query: DimRetentionSegment =====
let
    Source = #table(
        type table [RetentionSegment = text, SegmentOrder = Int64.Type, RiskTier = text, ValueTier = text, SuggestedAction = text],
        {
            {"High risk + high value", 1, "High", "high", "Hypothesis: personal outreach by an account manager to understand needs, then a tailored retention offer. Validate with a small pilot."},
            {"High risk + standard value", 2, "High", "standard", "Hypothesis: low-cost automated save offer plus an early-life check-in, since these customers are typically new. Validate before scaling."},
            {"Medium risk + high value", 3, "Medium", "high", "Hypothesis: an incentive to move from month-to-month to a longer contract. Test on a sample before a wide rollout."},
            {"Medium risk + standard value", 4, "Medium", "standard", "Hypothesis: contract-upgrade or autopay nudges through low-cost channels; test bundling security or support services."},
            {"Low risk + high value", 5, "Low", "high", "Hypothesis: protect with loyalty benefits and recognition; avoid discounts that may not be needed. Monitor for risk drift."},
            {"Low risk + standard value", 6, "Low", "standard", "Hypothesis: maintain service quality; test cross-selling protective services. No retention spend indicated."},
            {"Already churned", 7, "n/a", "n/a", "Not a retention target. Use for win-back or root-cause analysis only."}
        }
    )
in
    Source
